/* Stimmyz UI-only handoff: intentionally no real network/audio/recording pipeline. */
const icons=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialSounds=[
 {id:'red-sun',name:'Red Sun',file:'red-sun.png',color:0,duration:'00:16.40'},
 {id:'faaah',name:'FAAAH',file:'faaah.png',color:1,duration:'00:01.03'},
 {id:'bruh',name:'Bruh',file:'bruh.png',color:2,duration:'00:01.05'},
 {id:'hehe',name:'Hehe',file:'hehe.png',color:3,duration:'00:01.25'},
 {id:'cry-meme',name:'Cry meme',file:'cry-meme.png',color:4,duration:'00:02.46'},
 {id:'scooby',name:'Scooby laugh',file:'scooby.png',color:5,duration:'00:01.18'},
 {id:'yippee',name:'Yippee',file:'yippee.png',color:6,duration:'00:00.91'},
 {id:'metal-pipe',name:'Metal pipe',file:'metal-pipe.png',color:7,duration:'00:02.31'},
 {id:'airhorn',name:'Airhorn',file:'airhorn.png',color:8,duration:'00:01.22'},
 {id:'that-one',name:'That one',file:'that-one.png',color:9,duration:'00:01.11'},
 {id:'uwu',name:'UwU',file:'uwu.png',color:10,duration:'00:01.59'},
 {id:'creeper',name:'Creeper',file:'creeper.png',color:11,duration:'00:01.17'},
 {id:'vine-boom',name:'Vine boom',file:'vine-boom.png',color:12,duration:'00:01.42'},
 {id:'nope',name:'Nope',file:'nope.png',color:13,duration:'00:01.51'},
 {id:'troll',name:'Troll',file:'troll.png',color:14,duration:'00:01.83'}
];
const gradients=['linear-gradient(155deg,#ff5e68,#ff172c)','linear-gradient(145deg,#ff8c58,#ff4d43)','linear-gradient(150deg,#ffda57,#ffae22)','linear-gradient(155deg,#95f46c,#1bd48c)','linear-gradient(150deg,#3af6d8,#00b4d9)','linear-gradient(155deg,#37c9ff,#005aff)','linear-gradient(150deg,#9b6aff,#682bee)','linear-gradient(155deg,#ff5db3,#fa1583)','linear-gradient(155deg,#ff69ef,#e516cf)','linear-gradient(150deg,#ff9d93,#f5507d)','linear-gradient(155deg,#65d9ff,#00aaff)','linear-gradient(150deg,#9ced4a,#25d72c)','linear-gradient(155deg,#b560ff,#7433ef)','linear-gradient(155deg,#4ee2f5,#0475ee)','linear-gradient(150deg,#fc6eb5,#ee218a)'];
const state={theme:'Vanilla',build:'store',page:'board',menu:null,dialog:null,edit:false,board:'Main board',boards:['Main board','Work','Memes','Office'],quickAction:'record',sounds:initialSounds.map(s=>({...s,saved:['red-sun','faaah','cry-meme','scooby'].includes(s.id)})),search:'',librarySearch:'',sortAZ:true,toast:'',activeCreation:false,creationStep:'source',sourceName:'Lemongrab - Unacceptable!!!',total:9.35,start:2.52,end:5,playhead:3.58,fine:false,artMode:'default',artChoice:'yippee.png',artUploaded:null,onlineQuery:'',saveName:'Lemongrab - Unacceptable!!!',targetPad:null,recording:false};
const app=document.getElementById('app');
const themeSelect=document.getElementById('theme-select');
const buildSelect=document.getElementById('build-select');
const themeSwatches={'Peach':'#FFEAE6','Mint':'#EAFBF0','Snow':'#F8FAFC','Ice':'#E7F4FF','Vanilla':'#FFF8EC','Coffee':'#1F1B18'};
function titleCase(s){return s.replace(/^./,c=>c.toUpperCase())}
function menuButton(action,label,iconName,value='',css=''){return `<button class="${css}" data-action="${action}" data-value="${esc(value)}">${icons(iconName)}${esc(label)}</button>`}
function secondsText(s){const v=Math.max(0,Number(s)||0);return `00:${v.toFixed(2).padStart(5,'0')}`}
function displayBoard(){return state.board}
function boardSoundList(){const search=state.search.toLowerCase().trim();let ls=state.sounds;if(state.board==='Office')ls=ls.filter(x=>['bruh','cry-meme','airhorn','red-sun','troll','faaah'].includes(x.id)||x.id.startsWith('new-'));if(state.board==='Work')ls=ls.filter(x=>['faaah','bruh','scooby','airhorn','that-one','metal-pipe'].includes(x.id)||x.id.startsWith('new-'));if(state.board==='Memes')ls=ls.filter(x=>!['red-sun','airhorn','metal-pipe'].includes(x.id));return ls.filter(x=>x.name.toLowerCase().includes(search))}
function currentImage(s){return s.artData? s.artData: `assets/${s.file||'yippee.png'}`}
function renderStatus(){return `<header class="statusbar"><span>16:12</span><div class="status-right"><span>▂▄▆</span><span>◆</span><span>◕</span><span class="battery">90</span></div></header>`}
function navbar(){const tabs=[['board','board','BOARD'],['editor','editor','EDITOR'],['library','library','LIBRARY']];return `<nav class="navbar" aria-label="Main navigation">${tabs.map(([page,icon,label])=>`<button class="nav-tab ${state.page===page||state.activeCreation&&page==='editor'?'active':''}" data-action="navigate" data-value="${page}" aria-label="${label}">${icons(icon)}<span>${label}</span></button>`).join('')}</nav>`}
function settingsMenu(){if(state.menu!=='settings')return '';return `<div class="popup-menu settings-menu" role="menu">${menuButton('themeSheet','Choose theme','gear')}${menuButton('newBoard','New board','plus')}${menuButton('demoHelp','Prototype notes','file')}</div>`}
function boardMenu(){if(state.menu!=='board')return '';return `<div class="popup-menu board-list-menu" role="menu">${state.boards.map(x=>`<button data-action="selectBoard" data-value="${esc(x)}" class="${state.board===x?'selected':''}">${icons('controller')}${esc(x)} ${state.board===x?icons('check','small'):''}</button>`).join('')}${menuButton('newBoard','Create new board','plus')}</div>`}
function padMenu(sound){if(state.menu!==`pad:${sound.id}`)return '';return `<div class="popup-menu pad-action-menu" role="menu">${menuButton('replace','Replace sound','replace',sound.id)}${menuButton('renameSound','Rename','pencil',sound.id)}${menuButton('move','Move to board','swap',sound.id)}${menuButton('clear','Clear pad','trash',sound.id,'danger')}</div>`}
function quickMenu(){if(state.menu!=='quick')return '';return `<div class="popup-menu pad-action-menu align-left" role="menu">${menuButton('setQuick','Record new sound','mic','record')}${menuButton('setQuick','Choose local file','file','file')}${menuButton('setQuick','Open library','library','library')}</div>`}
function padHtml(s){return `<div class="sound-pad" data-color="${s.color%15}" style="--pad-color:${gradients[s.color%gradients.length]}"><button class="pad-main" data-action="playSound" data-value="${esc(s.id)}" aria-label="Play ${esc(s.name)}"><img class="pad-image" src="${esc(currentImage(s))}" alt=""/><span class="pad-label">${esc(s.name)}</span></button><button class="pad-menu-trigger" data-action="padMenu" data-value="${esc(s.id)}" aria-label="More options for ${esc(s.name)}">${icons('more')}</button>${padMenu(s)}</div>`}
function boardScreen(){return `<div class="screen"><div class="brand-row"><div class="brand">Stimmyz<span class="brand-spark">✦</span></div><div class="row-relative"><button class="icon-btn brand-more" data-action="settingsMenu" aria-label="More app options">${icons('more','large')}</button>${settingsMenu()}</div></div><div class="subheading">Soundboard</div><div class="board-actions"><div class="row-relative" style="flex:1;min-width:0"><button class="selector" data-action="boardMenu" aria-label="Choose board">${icons('controller','controller')}<span class="selector-label">${esc(displayBoard())}</span>${icons('chevron','small')}</button>${boardMenu()}</div><button class="outline-btn" data-action="editBoard">${icons(state.edit?'check':'pencil','small')} ${state.edit?'Done editing':'Edit board'}</button></div><div class="search-field">${icons('search')}<input type="search" placeholder="Search soundbites..." aria-label="Search soundbites" id="search-board" value="${esc(state.search)}"/></div>${state.edit?`<div class="edit-banner">${icons('pencil','small')} Editing your board · Configure Quick Add with its arrow</div>`:''}<div class="grid-wrap"><div class="sound-pad quick"><button class="quick-button" data-action="quickAdd" aria-label="Quick add a sound">${icons('plus')}<strong>Quick add</strong><span>${state.quickAction==='record'?'Record sound':state.quickAction==='file'?'Choose file':'Open library'}</span></button>${state.edit?`<button class="quick-arrow" data-action="quickMenu" aria-label="Configure quick add">${icons('chevron')}</button>`:''}${quickMenu()}</div>${boardSoundList().map(padHtml).join('')}</div>${boardSoundList().length===0?`<div class="empty-state">No sounds match your search.</div>`:''}</div>`}
function editorScreen(){return `<div class="screen"><div class="editor-head"><h1>Make a sound <span class="accent-spark">✦</span></h1><p>Turn any audio into a soundbite.</p></div><section class="card source-card"><div class="big-upload-icon">${icons('upload','xlarge')}<span class="badge-icon left">${icons('music','large')}</span><span class="badge-icon right">${icons('video','large')}</span></div><h2>Choose an audio or video file</h2><p class="desc">MP3, M4A, WAV, AAC, MP4, MOV<br/>up to 5 minutes and 32 MB.</p><button class="gradient-btn" data-action="chooseFile">Choose file</button></section>${state.build==='personal'?`<section class="card editor-link"><div class="section-title">${icons('link')} YouTube link (dev only)</div><p class="hint">For personal builds only.<br/>Not available in the Play Store version.</p><div class="link-row"><input class="textbox" id="youtube-link" placeholder="https://youtu.be/..." aria-label="YouTube link"><button class="soft-btn" data-action="youtubeDemo">Load audio</button></div></section>`:''}<div class="record-header">${icons('mic')} Or record a new sound</div><button class="record-btn" data-action="record">${icons('mic')} Start recording</button><p class="demo-badge">UI prototype · no media processing is performed</p></div>`}
function libraryMore(sound){if(state.menu!==`lib:${sound.id}`)return '';return `<div class="popup-menu library-action-menu" role="menu">${menuButton('playSound','Play','play',sound.id)}${menuButton('renameSound','Rename','pencil',sound.id)}${menuButton('changeArtwork','Change artwork','image',sound.id)}${menuButton('addBoard','Add to board','plus',sound.id)}${menuButton('delete','Delete','trash',sound.id,'danger')}</div>`}
function libraryScreen(){let list=state.sounds.filter(x=>x.saved && x.name.toLowerCase().includes(state.librarySearch.toLowerCase()));if(state.sortAZ)list=[...list].sort((a,b)=>a.name.localeCompare(b.name));return `<div class="screen"><div class="library-header">${icons('library')}<div><h1>Your library <span class="accent-spark">✦</span></h1><p>Saved sounds stay on this device.<br/>Add a clip to any pad for offline playback.</p></div></div><button class="gradient-btn library-primary" data-action="chooseFile">${icons('plus','small')} Edit a device file</button><div class="library-search-row"><div class="search-field">${icons('search')}<input type="search" id="search-library" value="${esc(state.librarySearch)}" placeholder="Search sounds..." aria-label="Search library"/></div><button class="sort-btn" data-action="sortLibrary" aria-label="Change library sorting">${icons('sort')}</button></div><div class="count">${list.length} / 1000 soundbites</div><div class="library-list">${list.map(s=>`<div class="library-row"><div class="lib-thumb" style="background:${gradients[s.color%15]}"><img src="${esc(currentImage(s))}" alt=""/></div><div class="lib-body"><strong>${esc(s.name)}</strong><small>${s.duration} · Saved offline</small></div><button class="round-play" data-action="playSound" data-value="${esc(s.id)}" aria-label="Play ${esc(s.name)}">${icons('play')}</button><button class="icon-btn lib-more" data-action="libraryMenu" data-value="${esc(s.id)}" aria-label="More options for ${esc(s.name)}">${icons('more')}</button>${libraryMore(s)}</div>`).join('')}</div><button class="new-sound" data-action="beginCreate"><span class="circle-plus">${icons('plus')}</span><strong>Make another sound</strong><small>Import or record a clip</small></button></div>`}
function stepper(){return `<div class="stepper">${[['source','Source'],['trim','Trim'],['details','Details']].map(([step,name],i)=>`<div class="step-item ${state.creationStep===step?'current':(step==='source'&&state.creationStep!=='source'||step==='trim'&&state.creationStep==='details')?'done':''}"><div class="circle">${(step==='source'&&state.creationStep!=='source'||step==='trim'&&state.creationStep==='details')?icons('check','tiny'):i+1}</div><span>${name}</span></div>`).join('')}</div>`}
function createFlowSource(){return state.recording?`<h2 class="detail-title">Recording a sound</h2><div class="card" style="text-align:center;padding:45px 20px"><span class="accent-spark" style="font-size:48px">${icons('mic','xlarge')}</span><p style="font-weight:800">Microphone recording (simulated)</p><p class="detail-hint">Tap Stop to use this recording in the Trim screen.</p></div><div class="flow-spacer"></div><button class="record-btn flow-bottom" data-action="record">${icons('stop')} Stop recording</button><button class="soft-btn flow-bottom" data-action="cancelCreate">Discard</button>`:`<h2 class="detail-title">Where's your audio from?</h2><button class="flow-source-option" data-action="chooseFile"><span class="round-icon">${icons('file')}</span><span><strong>Import from device</strong><small>Choose an audio or video file</small></span></button><button class="flow-source-option" data-action="record"><span class="round-icon">${icons('mic')}</span><span><strong>Record a new sound</strong><small>Use your microphone</small></span></button>${state.build==='personal'?`<button class="flow-source-option" data-action="youtubeDemo"><span class="round-icon">${icons('link')}</span><span><strong>Use a YouTube link (dev only)</strong><small>Personal development preview</small></span></button>`:''}<div class="flow-spacer"></div><button class="soft-btn flow-bottom" data-action="cancelCreate">Cancel</button>`}
const waveHeights=Array.from({length:64},(_,i)=>Math.round(14+Math.abs(Math.sin(i*1.92)*33)+Math.abs(Math.sin(i*.41)*17)));
function waveform(){let l=state.start/state.total*100,r=state.end/state.total*100,p=state.playhead/state.total*100;return `<div class="waveform" id="waveform" aria-label="Interactive waveform; drag the start and end handles"><div class="wave-bars">${waveHeights.map(h=>`<i style="height:${h}%"></i>`).join('')}</div><div class="wave-selection" id="wave-selection" style="left:${l}%;width:${r-l}%"><div class="bar-highlighter"></div></div><div class="wave-playhead" style="left:${p}%"></div><button class="wave-handle" data-handle="start" style="left:${l}%" aria-label="Drag clip start"></button><button class="wave-handle" data-handle="end" style="left:${r}%" aria-label="Drag clip end"></button></div>`}
function fineTune(){return `<div class="fine-tune"><button class="fine-head" data-action="toggleFine">Fine tune <span>(optional) ${icons('chevron','small')}</span></button>${state.fine?`<div class="fine-grid"><strong>Start</strong><code id="fine-start">${secondsText(state.start)}</code>${[-1,-.1,.1,1].map(n=>`<button data-action="fineStart" data-value="${n}">${n>0?'+':''}${Math.abs(n)<1?(n*1000)+'ms':n+'s'}</button>`).join('')}<strong>End</strong><code id="fine-end">${secondsText(state.end)}</code>${[-1,-.1,.1,1].map(n=>`<button data-action="fineEnd" data-value="${n}">${n>0?'+':''}${Math.abs(n)<1?(n*1000)+'ms':n+'s'}</button>`).join('')}</div>`:''}</div>`}
function createFlowTrim(){return `<div class="trim-source"><div class="trim-source-icon">🔊</div><div class="trim-source-text"><strong>${esc(state.sourceName)}</strong><small>${secondsText(state.total)} total · Up to 60 seconds</small></div></div><div class="wave-card">${waveform()}<div class="times"><span id="time-start">${secondsText(state.start)}</span><span id="time-selected">${secondsText(state.end-state.start)} selected</span><span id="time-end">${secondsText(state.end)}</span></div><button class="preview-btn" data-action="previewTrim">${icons('play')} Preview selection</button></div>${fineTune()}<div class="selection-info">Drag both waveform handles to select the moment. Fine tune is optional.</div><div class="flow-spacer"></div><button class="gradient-btn flow-bottom" data-action="nextDetails">Next →</button>`}
function previewArt(){if(state.artUploaded)return `<img src="${state.artUploaded}" alt="Uploaded artwork preview"/>`;if(state.artMode==='default')return icons('music','xlarge');return `<img src="assets/${esc(state.artChoice)}" alt="Selected artwork preview"/>`}
function createFlowDetails(){return `<h2 class="detail-title">Make it yours <span class="accent-spark">✦</span></h2><div class="artwork-summary"><div class="artwork-preview">${previewArt()}</div><div><strong>Optional artwork</strong><p>Choose a picture for your pad or keep the default icon.</p></div></div><label class="fieldlabel" for="sound-name">SOUNDBITE NAME</label><input id="sound-name" class="textbox" maxlength="100" value="${esc(state.saveName)}" aria-label="Soundbite name"/><div class="details-options"><button class="art-option ${state.artMode==='default'?'active':''}" data-action="artDefault">${icons('music')} Default</button><button class="art-option" data-action="artGallery">${icons('image')} Gallery</button><button class="art-option ${state.artMode==='search'?'active':''}" data-action="artSearch">${icons('search')} Search</button></div>${state.artMode==='search'?`<p class="detail-hint">Online artwork search requires a licensed API. Results below are UI placeholders only.</p><input class="textbox" id="art-query" placeholder="Search, e.g. reaction cat" value="${esc(state.onlineQuery)}"/><div class="art-search-grid">${['😸','🤖','💜','🌈'].map((x,i)=>`<button data-action="selectOnlineArt" data-value="${i}" aria-label="Choose sample sticker ${i+1}">${x}</button>`).join('')}</div>`:''}<p class="detail-hint">Your clip and optional artwork will be stored on the device. You can skip artwork.</p><div class="flow-spacer"></div><button class="gradient-btn flow-bottom" data-action="saveSound">Save soundbite</button>`}
function createScreen(){return `<div class="screen create-screen"><div class="flow-header"><button class="icon-btn" data-action="${state.creationStep==='source'?'cancelCreate':'flowBack'}" aria-label="Back">${icons(state.creationStep==='source'?'close':'arrow','large')}</button><h1>Create a sound</h1><span style="width:36px"></span></div>${stepper()}${state.creationStep==='source'?createFlowSource():state.creationStep==='trim'?createFlowTrim():createFlowDetails()}</div>`}
function modal(){if(state.dialog==='themes')return `<div class="floating-theme"><div class="theme-sheet"><h2>Choose your mood ✦</h2><p>Six approved Stimmyz themes. Your sound pad artwork and sizing stay the same.</p><div class="theme-grid">${Object.keys(themeSwatches).map(x=>`<button class="theme-choice ${state.theme===x?'active':''}" data-action="theme" data-value="${x}"><span class="theme-blob" style="background:${themeSwatches[x]}"></span>${x}</button>`).join('')}</div><button class="soft-btn" style="width:100%" data-action="closeDialog">Done</button></div></div>`;
if(!state.dialog)return '';
let d=state.dialog;let s=state.sounds.find(x=>x.id===d.id);let title=d.type==='rename'?'Rename sound':d.type==='newBoard'?'Create board':d.type==='clear'?'Clear sound pad?':d.type==='delete'?'Delete sound?':d.type==='move'?'Move sound to board':d.type==='addBoard'?'Add sound to board':'Notice';return `<div class="modal-scrim"><div class="dialog" role="dialog" aria-modal="true"><h2>${title}</h2>${d.type==='rename'||d.type==='newBoard'?`<input class="textbox" id="dialog-field" value="${d.type==='rename'?esc(s?.name||''):''}" placeholder="Name"/>`:''}${d.type==='delete'||d.type==='clear'?`<p class="detail-hint">${esc(s?.name||'This clip')} will ${d.type==='delete'?'be deleted from the demo library':'be removed from this board'}. This demonstration can be reset by reloading.</p>`:''}${d.type==='move'||d.type==='addBoard'?`<div class="theme-grid" style="grid-template-columns:1fr 1fr">${state.boards.map(x=>`<button class="theme-choice" data-action="confirmBoardMove" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:''}<div class="row"><button class="soft-btn" data-action="closeDialog">Cancel</button>${!['move','addBoard'].includes(d.type)?`<button class="gradient-btn" data-action="confirmDialog">${d.type==='delete'||d.type==='clear'?'Confirm':'Save'}</button>`:''}</div></div></div>`}
function render(preserveScroll=true){const oldScroll=preserveScroll?app.querySelector('.screen')?.scrollTop||0:0;app.dataset.theme=state.theme;app.innerHTML=renderStatus()+(state.activeCreation?createScreen():state.page==='board'?boardScreen():state.page==='editor'?editorScreen():libraryScreen())+(state.activeCreation?'':navbar())+modal()+(state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'');const screen=app.querySelector('.screen');if(screen&&preserveScroll)screen.scrollTop=oldScroll;themeSelect.value=state.theme;buildSelect.value=state.build;document.querySelectorAll('[data-preview-page]').forEach(el=>el.classList.toggle('selected',el.dataset.previewPage===(state.activeCreation?state.creationStep:state.page)));attachWave();}
function notify(message){state.toast=message;render();clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>{state.toast='';render()},2500)}
function startCreate(step='source'){state.activeCreation=true;state.creationStep=step;state.menu=null;state.fine=false;state.artMode='default';state.saveName=state.sourceName;render(false)}
function startTrim(name){state.sourceName=name||'New recording';state.saveName=state.sourceName;state.total=9.35;state.start=2.52;state.end=5;state.playhead=3.58;startCreate('trim')}
function closeMenus(){state.menu=null}
function showDialog(type,id){state.menu=null;state.dialog={type,id};render()}
function processAction(action,value,button){const sound=state.sounds.find(x=>x.id===value);switch(action){
 case 'navigate':state.page=value;state.activeCreation=false;state.menu=null;state.edit=false;state.search='';state.librarySearch='';render(false);break;
 case 'settingsMenu':state.menu=state.menu==='settings'?null:'settings';render();break;
 case 'boardMenu':state.menu=state.menu==='board'?null:'board';render();break;
 case 'selectBoard':state.board=value;state.menu=null;render(false);break;
 case 'editBoard':state.edit=!state.edit;state.menu=null;render();break;
 case 'padMenu':state.menu=state.menu===`pad:${value}`?null:`pad:${value}`;render();break;
 case 'libraryMenu':state.menu=state.menu===`lib:${value}`?null:`lib:${value}`;render();break;
 case 'quickMenu':state.menu=state.menu==='quick'?null:'quick';render();break;
 case 'setQuick':state.quickAction=value;state.menu=null;notify(`Quick Add action: ${value==='record'?'Record':value==='file'?'Choose file':'Library'}`);break;
 case 'quickAdd':if(state.edit){state.menu='quick';render()}else if(state.quickAction==='record')processAction('record');else if(state.quickAction==='file')processAction('chooseFile');else processAction('navigate','library');break;
 case 'themeSheet':state.dialog='themes';state.menu=null;render();break;
 case 'theme':state.theme=value;state.dialog='themes';render();break;
 case 'closeDialog':state.dialog=null;render();break;
 case 'newBoard':showDialog('newBoard');break;
 case 'playSound':notify(`▶ ${sound?.name||'Sound'} — playback is simulated`);break;
 case 'replace':state.targetPad=value;startCreate('source');break;
 case 'renameSound':showDialog('rename',value);break;
 case 'move':showDialog('move',value);break;
 case 'clear':showDialog('clear',value);break;
 case 'delete':showDialog('delete',value);break;
 case 'addBoard':showDialog('addBoard',value);break;
 case 'changeArtwork':state.targetPad=value;state.saveName=sound?.name||'Sound';state.sourceName=state.saveName;startCreate('details');break;
 case 'confirmBoardMove':state.board=value;state.dialog=null;notify(`Assigned to ${value} (UI demo)`);break;
 case 'confirmDialog':confirmDialog();break;
 case 'beginCreate':state.targetPad=null;startCreate('source');break;
 case 'chooseFile':document.getElementById('audio-input').click();break;
 case 'record':state.recording=!state.recording;if(state.recording){state.dialog=null;startCreate('source');notify('Recording started (UI simulation). Tap Record again to finish.')}else{startTrim('My recording');notify('Recording preview loaded (UI simulation).')}break;
 case 'youtubeDemo':if(state.build==='personal')startTrim('YouTube excerpt (demo)');else notify('Unavailable in the Play Store build');break;
 case 'cancelCreate':state.activeCreation=false;state.recording=false;state.menu=null;render(false);break;
 case 'flowBack':if(state.creationStep==='details')state.creationStep='trim';else if(state.creationStep==='trim')state.creationStep='source';else state.activeCreation=false;render(false);break;
 case 'toggleFine':state.fine=!state.fine;render();break;
 case 'fineStart':state.start=Math.min(Math.max(state.start+Number(value),0),state.end-.1);render();break;
 case 'fineEnd':state.end=Math.min(Math.max(state.end+Number(value),state.start+.1),Math.min(state.total,state.start+60));render();break;
 case 'previewTrim':notify(`▶ Preview ${secondsText(state.end-state.start)} — UI simulation`);break;
 case 'nextDetails':state.creationStep='details';state.saveName=state.sourceName;render(false);break;
 case 'artDefault':state.artMode='default';state.artUploaded=null;render();break;
 case 'artGallery':document.getElementById('art-input').click();break;
 case 'artSearch':state.artMode='search';render();break;
 case 'selectOnlineArt':state.artMode='selected';state.artChoice=['cry-meme.png','metal-pipe.png','yippee.png','uwu.png'][Number(value)];render();break;
 case 'saveSound':saveSound();break;
 case 'sortLibrary':state.sortAZ=!state.sortAZ;render();notify(state.sortAZ?'Sorted A–Z':'Original library order');break;
 case 'demoHelp':state.menu=null;notify('This HTML demonstrates UI behavior. Review the handoff for Android implementation.');break;
 default:break;}}
function confirmDialog(){const d=state.dialog;if(!d)return;const inp=document.getElementById('dialog-field')?.value.trim();if(d.type==='newBoard'){if(!inp){notify('Enter a board name');return;}if(!state.boards.includes(inp))state.boards.push(inp);state.board=inp;}
if(d.type==='rename'&&inp){const s=state.sounds.find(x=>x.id===d.id);if(s)s.name=inp}
if(d.type==='delete'||d.type==='clear'){state.sounds=state.sounds.filter(x=>x.id!==d.id)}state.dialog=null;render();}
function saveSound(){const name=document.getElementById('sound-name')?.value.trim()||'New sound';if(state.targetPad){const s=state.sounds.find(x=>x.id===state.targetPad);if(s){s.name=name;if(state.artUploaded)s.artData=state.artUploaded;else if(state.artMode==='selected')s.file=state.artChoice;}state.targetPad=null}else{state.sounds.push({id:`new-${Date.now()}`,name,color:state.sounds.length%gradients.length,file:state.artChoice,duration:secondsText(state.end-state.start),artData:state.artUploaded,saved:true})}state.activeCreation=false;state.page='board';state.menu=null;state.search='';state.artUploaded=null;notify('Soundbite saved in demo · Quick Add stayed at #1')}
function attachWave(){const wave=document.getElementById('waveform');if(!wave)return;let active=null;const clamp=(v,min,max)=>Math.min(Math.max(v,min),max);const updateVisual=()=>{let sel=document.getElementById('wave-selection');if(!sel)return;sel.style.left=(state.start/state.total*100)+'%';sel.style.width=((state.end-state.start)/state.total*100)+'%';for(const h of wave.querySelectorAll('[data-handle]'))h.style.left=((h.dataset.handle==='start'?state.start:state.end)/state.total*100)+'%';let a=document.getElementById('time-start'),b=document.getElementById('time-end'),c=document.getElementById('time-selected');if(a)a.textContent=secondsText(state.start);if(b)b.textContent=secondsText(state.end);if(c)c.textContent=secondsText(state.end-state.start)+' selected'};
wave.onpointerdown=e=>{let h=e.target.closest('[data-handle]');if(!h)return;active=h.dataset.handle;e.preventDefault();wave.setPointerCapture(e.pointerId)};
wave.onpointermove=e=>{if(!active)return;let rect=wave.getBoundingClientRect();let sec=clamp((e.clientX-rect.left)/rect.width,0,1)*state.total;if(active==='start')state.start=clamp(sec,0,state.end-.1);else state.end=clamp(sec,state.start+.1,Math.min(state.total,state.start+60));updateVisual()};
wave.onpointerup=e=>{if(!active)return;active=null;try{wave.releasePointerCapture(e.pointerId)}catch{};render()};wave.onpointercancel=()=>{active=null;render()};}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const v=b.dataset.value||'';processAction(a,v,b)});
app.addEventListener('input',e=>{const el=e.target;if(el.id==='search-board'){state.search=el.value;let pos=el.selectionStart;render();const input=document.getElementById('search-board');if(input){input.focus();input.setSelectionRange(pos,pos)}}else if(el.id==='search-library'){state.librarySearch=el.value;let pos=el.selectionStart;render();const input=document.getElementById('search-library');if(input){input.focus();input.setSelectionRange(pos,pos)}}else if(el.id==='sound-name')state.saveName=el.value;else if(el.id==='art-query')state.onlineQuery=el.value});
document.getElementById('audio-input').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)startTrim(f.name.replace(/\.[^.]+$/,''));e.target.value=''});
document.getElementById('art-input').addEventListener('change',e=>{let f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{state.artUploaded=String(reader.result);state.artMode='gallery';render()};reader.readAsDataURL(f);e.target.value=''});
themeSelect.addEventListener('change',e=>{state.theme=e.target.value;render()});buildSelect.addEventListener('change',e=>{state.build=e.target.value;state.menu=null;render()});
document.querySelectorAll('[data-preview-page]').forEach(btn=>btn.addEventListener('click',()=>{const page=btn.dataset.previewPage;state.activeCreation=['trim','details'].includes(page);state.creationStep=state.activeCreation?page:'source';state.page=state.activeCreation?'editor':page;state.dialog=null;state.menu=null;render(false)}));
render(false);
